'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-2h3z',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',smile:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M8 14s1 3 4 3 4-3 4-3 M8 9h.01M16 9h.01',bowl:'M3 11h18c0 5-3 8-9 8s-9-3-9-8ZM7 21h10 M9 7l2-4M14 7l2-4',train:'M5 15V5c0-2 14-2 14 0v10a3 3 0 0 1-3 3H8a3 3 0 0 1-3-3ZM5 10h14M8 14h.01M16 14h.01M8 18l-2 3m10-3 2 3',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',bed:'M3 18V7m0 7h18v4M3 10h5v4m0-5h10a3 3 0 0 1 3 3v2M3 18v3m18-3v3',bag:'M5 7h14l2 14H3ZM8 7V6a4 4 0 0 1 8 0v1',chat:'M21 11a9 8 0 0 1-9 8H6l-4 3 1-7a8 8 0 0 1 0-8 9 8 0 0 1 18 4ZM7 10h10M7 14h6',help:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M9.5 8.5a2.5 2.5 0 0 1 5 0c0 2-2.5 2-2.5 4M12 16h.01',mountain:'m2 20 7-14 4 7 3-5 6 12ZM6 12l3 2 2-3',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',fire:'M12 2c2 6 7 7 7 13a7 7 0 0 1-14 0c0-4 3-6 4-8 0 3 2 4 3 4 2-2 1-5 0-9Z',sound:'M4 9h4l5-4v14l-5-4H4zM16 8a6 6 0 0 1 0 8M19 5a10 10 0 0 1 0 14',review:'M3 10a9 9 0 1 1 1 7M3 4v6h6 M12 7v5l3 2',kana:'M4 5h12M10 2v3M7 8c0 5 4 9 9 10M14 5c0 7-4 13-10 15m11 0 4-10 4 10m-6-4h4',chart:'M4 20V10h4v10M10 20V5h4v15M16 20V2h4v18',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M9 3h6l1 3 3 1 2 5-2 3-1 4-5 2-3-2-4-1-2-5 2-3 1-4z',mic:'M9 5a3 3 0 0 1 6 0v7a3 3 0 0 1-6 0zM6 10v2a6 6 0 0 0 12 0v-2M12 18v4M8 22h8',leaf:'M20 3C9 2 3 7 4 14s10 10 14 2c2-4 2-8 2-13ZM6 18 16 7',bookmark:'M6 3h12v18l-6-4-6 4z',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',flag:'M5 21V3c5-4 9 4 14 0v10c-5 4-9-4-14 0'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true" viewBox="0 0 24 24"><path d="${paths[name]||paths.spark}"/></svg>`;
const KEY='tabi.learning.v1';
const fresh=()=>({version:1,completed:[],reviews:{},history:{},saved:[],settings:{romaji:true,goal:30},conversations:{},studio:window.TabiStudio?.fresh()});
let state=fresh(),storageOK=true;
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));}catch(e){storageOK=false;}
function validate(s){if(!s||s.version!==1||!Array.isArray(s.completed)||!s.reviews||!s.history)throw Error('Invalid backup');const n=fresh();n.completed=[...new Set(s.completed.filter(x=>/^\d+-\d+$/.test(x)&&COURSE[+x.split('-')[0]]?.lessons[+x.split('-')[1]]))];for(const [id,r]of Object.entries(s.reviews)){if(/^\d+-\d+-\d+$/.test(id)&&r&&Number.isFinite(r.due)&&Number.isFinite(r.level))n.reviews[id]={due:r.due,level:Math.max(0,Math.min(5,r.level))};}for(const [d,v]of Object.entries(s.history)){if(/^\d{4}-\d{2}-\d{2}$/.test(d)&&v&&Number.isFinite(v.xp)&&v.xp>=0)n.history[d]={xp:v.xp,lessons:Array.isArray(v.lessons)?v.lessons.filter(x=>typeof x==='string'):[]};}n.saved=Array.isArray(s.saved)?s.saved.filter(x=>/^\d+-\d+-\d+$/.test(x)):[];n.settings={romaji:s.settings?.romaji!==false,goal:[15,30,50].includes(s.settings?.goal)?s.settings.goal:30};n.conversations=s.conversations&&typeof s.conversations==='object'?s.conversations:{};n.studio=window.TabiStudio?.restore(s.studio);return n;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('Progress could not be saved. Export a backup in Settings.');}}
function dateKey(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function daysAgo(n){let d=new Date();d.setDate(d.getDate()-n);return dateKey(d);}
function streak(){let n=0,i=state.history[dateKey()]?.xp?0:1;for(;i<3660;i++){if(!state.history[daysAgo(i)]?.xp)break;n++;}return n;}
const todayXP=()=>state.history[dateKey()]?.xp||0;
const totalXP=()=>Object.values(state.history).reduce((a,x)=>a+x.xp,0);
const cards=[];COURSE.forEach((u,ui)=>u.lessons.forEach((l,li)=>l[3].forEach((p,pi)=>cards.push({id:`${ui}-${li}-${pi}`,p,ui,li}))));
const byId=id=>cards.find(x=>x.id===id);
const dueCards=()=>cards.filter(x=>state.reviews[x.id]?.due<=Date.now());
function nextLesson(){for(let u=0;u<COURSE.length;u++)for(let l=0;l<3;l++)if(!state.completed.includes(`${u}-${l}`))return [u,l];return null;}
function unlocked(u,l){if(u===0&&l===0)return true;return state.completed.includes(l===0?`${u-1}-2`:`${u}-${l-1}`);}
function shuffle(a){return [...a].sort(()=>Math.random()-.5);}
function normalize(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ou/g,'o').replace(/oo/g,'o').replace(/uu/g,'u').replace(/[^a-z0-9ぁ-んァ-ヶ一-龯]/g,'');}
function accepted(v,p){return normalize(v)===normalize(p[0])||normalize(v)===normalize(p[1]);}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
let voices=[];function updateVoices(){voices=window.speechSynthesis?.getVoices()||[];}updateVoices();if(window.speechSynthesis)window.speechSynthesis.addEventListener('voiceschanged',updateVoices);
function japaneseVoice(){updateVoices();const available=voices.filter(v=>v.lang.toLowerCase().startsWith('ja'));return available.find(v=>v.localService===true)||(navigator.onLine!==false?available[0]:null);}
function hasVoice(){return !!japaneseVoice();}
function voiceStatusText(){const voice=japaneseVoice();return voice?(voice.localService?'A local Japanese voice is available for offline playback. Test it in airplane mode before travelling.':'A Japanese voice is available online. Download a Japanese system voice for offline audio.'):(navigator.onLine===false?'No local Japanese voice is available. Reading practice works offline. Connect to download a Japanese voice in your phone settings.':'No Japanese voice detected. Download or enable a Japanese text-to-speech voice on your device, then reload.');}
function speak(t,rate=.8){const voice=japaneseVoice();if(!voice){toast(navigator.onLine===false?'Offline audio needs a downloaded Japanese device voice. Reading practice is still available.':'Enable a Japanese text-to-speech voice on your device, then reload.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang='ja-JP';u.rate=rate;u.voice=voice;u.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))toast('Audio could not play. Try a downloaded Japanese device voice; reading practice remains available.');};speechSynthesis.speak(u);}

const japanArt=`<svg class="hero-art" viewBox="0 0 280 260" fill="none" aria-hidden="true"><circle cx="190" cy="71" r="31" fill="#DF8C6D" opacity=".65"/><path d="M6 203 113 77l115 126" fill="#B2C4A8"/><path d="m77 120 36-43 37 43-24-8-14 12-13-12Z" fill="#FAFAEE"/><path d="M0 237c55-51 84-36 137-12 63-63 107-72 143-43v78H0Z" fill="#92AA88"/><path d="M0 260v-27c52-10 91-2 139 27Z" fill="#6E906E"/><path d="M236 260c-27-35-76-31-50-60 11-12 40-18 61-20-36 16-53 23-36 34 20 11 41 25 53 46" fill="#D7DFCA"/><g transform="translate(159 102)"><path d="M16 138V22h44v116" fill="#DDD9BE"/><path d="M24 138V26h9v112m11 0V26h9v112" fill="#937B58"/><path d="M7 31h62v8H7zM1 21l11-8h52l11 8-7 6H8Z" fill="#7C6950"/><path d="M8 65h60v7H8zM3 56l12-9h46l12 9-5 5H8Z" fill="#887353"/><path d="M9 98h57v7H9zM3 89l12-9h45l12 9-5 5H9Z" fill="#8E7858"/><path d="M38 0v13M32 7h12" stroke="#7C6950" stroke-width="3"/></g><g transform="translate(38 164) rotate(-12)"><rect width="66" height="86" rx="7" fill="#EDE6CE" stroke="#E1D7B9"/><rect x="8" y="9" width="50" height="68" rx="3" stroke="#C3B793"/><circle cx="33" cy="35" r="13" stroke="#A99D75"/><path d="M20 35h26M33 22v26M27 24c-4 6-4 16 0 22m12-22c4 6 4 16 0 22M20 59h26m-20 6h14" stroke="#A99D75"/><text x="18" y="15" fill="#A99D75" font-size="5" letter-spacing="1">PASSPORT</text></g><path d="M231 118c8-8 13-7 18-1m-6-23c7-8 14-8 20-2" stroke="#6D896A" stroke-width="2" stroke-linecap="round"/><circle cx="35" cy="113" r="3" fill="#A3B899"/><circle cx="253" cy="144" r="3" fill="#A3B899"/></svg>`;
let page='learn',expanded=new Set([0]),kanaType=1,phraseFilter='',phraseQuery='',savedOnly=false,convMode='guided',session=null;
function nav(){return [['learn','book','Learn'],['studio','spark','Studio'],['practice','review','Review'],['conversations','chat','Conversations'],['phrases','bookmark','Phrasebook'],['kana','kana','Kana'],['progress','chart','Progress']].map(([p,i,t])=>`<button data-nav="${p}" class="${page===p?'active':''}" ${page===p?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${p==='practice'&&dueCards().length?`<span class="badge">${dueCards().length}</span>`:''}</button>`).join('');}
function render(){const n=nextLesson();if(n)expanded.add(n[0]);$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="brandmark">旅</span><span class="brandword">tabi<span style="color:#DD6D50">.</span></span></div><div class="tagline">JAPANESE FOR THE JOURNEY</div><nav class="nav" aria-label="Main navigation">${nav()}</nav><div class="sidebar-bottom"><div class="trip-note">${icon('flag')}<h4>Little steps. Big adventures.</h4><p>A few minutes today.<br>A real conversation tomorrow.</p></div><button class="profile" data-nav="settings" aria-label="Open settings"><span class="avatar">旅</span><div><strong>Your travel journal</strong><span>Beginner · Japanese</span></div>${icon('settings')}</button></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb"><span class="mobilebrand"><span class="brandmark">旅</span>tabi.</span><span class="flag desktoptext"></span><span class="desktoptext">JAPANESE</span><span class="desktoptext" style="color:#C8CFBF">/</span><span class="desktoptext">BEGINNER PATH</span></div><div class="stats"><span title="Consecutive days practised">${icon('fire')}${streak()}<span class="desktoptext"> day streak</span></span><span class="xp">${icon('spark')}${totalXP()} XP</span><button class="audio-icon" data-nav="settings" aria-label="Settings" style="width:30px;height:30px">${icon('settings')}</button></div></header><div id="pwa-status" class="offline-strip" role="status" aria-live="polite"></div><div class="layout">${page==='learn'?learnPage():`<main class="main wide">${pageContent()}</main>`}</div></div>`;bind();updatePwaUI();}
function learnPage(){const n=nextLesson(),allDone=!n,done=state.completed.length,pct=Math.round(done/30*100);return `<main class="main"><div class="welcome"><div><h2>${done?'Welcome back, adventurer.':'Your Japan journey starts here.'}</h2><p>Small lessons. Real conversations. A little closer to Japan.</p></div><span class="daylabel">一歩ずつ · ONE STEP AT A TIME</span></div><section class="hero"><div class="hero-copy"><div class="eyebrow">${done?'KEEP YOUR CURIOSITY GOING':'A NEW LANGUAGE. A NEW ADVENTURE.'}</div><h2>Your next stop:<br>a little more Japanese.</h2><p>From your first こんにちは to ordering your favourite ramen.</p><button class="primary" id="continue">${allDone?'Review your Japanese':done?'Continue learning':'Start your journey'}${icon('arrow')}</button></div>${japanArt}</section><button type="button" class="studio-entry" data-nav="studio"><span class="studio-icon">${icon('spark')}</span><span><strong>Immersion Studio</strong><small>Read, listen, save words and follow a daily plan.</small></span>${icon('arrow')}</button><div class="section-title"><h2>Your learning path</h2><span>${done} / 30 lessons complete</span></div><div class="progressbar" style="height:4px;margin-top:-9px;margin-bottom:26px"><i style="width:${pct}%"></i></div>${COURSE.map((u,ui)=>`${ui%2===0?`<div class="path-header"><span class="section-chip">CHAPTER ${Math.floor(ui/2)+1}</span><p>${['The first connection','Out into the city','Feel at home','A little more independent','Ready for your adventure'][Math.floor(ui/2)]}</p></div>`:''}${unitCard(u,ui,n)}`).join('')}<p class="storage-note">Your progress is saved on this browser. Export a backup in Settings to move devices.</p></main><aside class="right">${dailyCard()}<div class="card phrase-day"><div class="eyebrow">A LITTLE JAPANESE, EVERY DAY</div><div class="card-heading"><h3>Words for the road</h3><span style="color:#A09072">旅</span></div><div class="jp">${dayPhrase()[0]}</div>${state.settings.romaji?`<div class="romaji">${dayPhrase()[1]}</div>`:''}<div class="meaning">${dayPhrase()[2]}</div><button class="audio" id="day-audio">${icon('sound')}Hear it in Japanese</button></div><div class="culture"><h4>${icon('leaf')}A little cultural note</h4><p>A simple すみません goes a long way. Use it to get someone’s attention, ask for help, or offer a small apology.</p></div></aside>`;}
function dayPhrase(){return cards[(Math.floor(Date.now()/86400000)*7)%cards.length].p;}
function unitCard(u,ui,n){const completed=u.lessons.filter((l,li)=>state.completed.includes(`${ui}-${li}`)).length,lock=!unlocked(ui,0),current=n?.[0]===ui,open=expanded.has(ui);return `<section class="unit ${current?'current':''} ${lock?'locked':''}" style="--unitcolor:${u.color}33"><button class="unit-header" data-unit="${ui}" aria-expanded="${open}"><span class="unit-icon">${icon(u.icon)}</span><div class="unit-info"><small>UNIT ${String(ui+1).padStart(2,'0')} · ${u.jp}</small><h3>${u.title}</h3><p>${u.goal}</p></div><div class="unit-meta"><span>${completed}/3</span>${icon(completed===3?'check':lock?'lock':open?'down':'chevron')}</div></button>${open?`<div class="lessons">${u.lessons.map((l,li)=>{let d=state.completed.includes(`${ui}-${li}`),nx=n?.[0]===ui&&n?.[1]===li,lk=!unlocked(ui,li);return `<div class="lesson-row ${d?'done':''} ${nx?'next':''}"><span class="lesson-node">${d?icon('check'):lk?icon('lock'):li+1}</span><div class="lessontext"><strong>${l[0]}</strong><small>4 phrases · 6–8 min${li===2?' · unit recap':''}</small></div><button class="start" data-lesson="${ui}-${li}" ${lk?'disabled':''}>${d?'REVISIT':nx?'START':'LESSON'}</button></div>`;}).join('')}${lock?'<p class="muted" style="font-size:11px;padding-top:10px">Finish the previous unit to unlock these lessons. You can explore all phrases in the Phrasebook.</p>':''}</div>`:''}</section>`;}
function dailyCard(){const pct=Math.min(100,todayXP()/state.settings.goal*100);return `<section class="card"><div class="card-heading"><h3>Your daily goal</h3><small>${todayXP()>=state.settings.goal?'Nicely done!':'A little, every day'}</small></div><div class="goal-ring" style="--pct:${pct}%"><div class="ringcopy"><strong>${todayXP()}<span style="font-size:14px;color:#A5AF9A"> / ${state.settings.goal}</span></strong><small>XP TODAY</small></div></div><p class="card-caption">${todayXP()>=state.settings.goal?'One more step towards Japan.':'One short lesson is a lovely start.'}</p><div class="week">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let key=dateKey(d);return `<div class="weekday ${i===6?'today':''} ${state.history[key]?.xp?'did':''}">${['S','M','T','W','T','F','S'][d.getDay()]}<b>${state.history[key]?.xp?'✓':d.getDate()}</b></div>`;}).join('')}</div></section>`;}
function pageContent(){switch(page){case'studio':return window.TabiStudio.html();case'practice':return practicePage();case'phrases':return phrasesPage();case'conversations':return conversationPage();case'kana':return kanaPage();case'progress':return progressPage();case'settings':return settingsPage();default:return '';}}
const intro=(tag,title,desc)=>`<div class="page-intro"><div class="eyebrow">${tag}</div><h1>${title}</h1><p>${desc}</p></div>`;
function practicePage(){const due=dueCards().length,learned=Object.keys(state.reviews).length;let next=Object.values(state.reviews).filter(x=>x.due>Date.now()).sort((a,b)=>a.due-b.due)[0];return intro('MAKE IT STICK','A little practice goes a long way.','Bring familiar words back, just before they slip away. Say each answer aloud before you check it.')+`<div class="grid2"><div class="featurecard"><span class="unit-icon" style="background:#E8EEDC">${icon('review')}</span><span class="pill">SPACED REPETITION</span><h2>${due?`${due} phrases ready to revisit`:'You’re all caught up.'}</h2><p>${learned?`You have ${learned} phrases in your review collection. Correct answers return in 1, 3, 7, 14, then 30 days.${next?` Next review: ${new Date(next.due).toLocaleDateString(undefined,{month:'short',day:'numeric'})}.`:''}`:'Complete your first lesson to start your personal review collection. Mistakes return sooner; familiar phrases get more breathing room.'}</p><button class="primary" id="review-due" ${!due?'disabled':''}>Review ${Math.min(10,due)} phrases${icon('arrow')}</button></div><div class="featurecard"><span class="unit-icon" style="background:#F2E6D4">${icon('spark')}</span><span class="pill" style="background:#F2EBDC;color:#A08A60">RECALL WITHOUT HINTS</span><h2>From memory, to real life.</h2><p>Practise a mix of learned phrases. Type the Japanese or romaji yourself, with no multiple-choice hints.</p><button class="secondary" id="review-all" ${!learned?'disabled':''}>Practise from memory${icon('arrow')}</button></div></div><div class="info">A useful rhythm: learn a lesson, say the phrases out loud, then revisit them tomorrow. Review has no hearts, timers, or penalties.</div><div class="outline"><h3>Make the pattern yours</h3><p>After each lesson, swap one word: 水をください → コーヒーをください. Then imagine a real person asking you a question. Recall builds a different skill from recognising an answer.</p><button class="linkbtn" data-nav="conversations">Try a conversation${icon('arrow')}</button></div>`;}
function phrasesPage(){const filtered=cards.filter(c=>(!phraseFilter||c.ui===+phraseFilter)&&(!savedOnly||state.saved.includes(c.id))&&normalize(c.p.join(' ')).includes(normalize(phraseQuery)));return intro('YOUR POCKET TRAVEL COMPANION','Words for wherever you wander.','Search all 120 phrases, listen, and save your favourites. Available from day one, even before you unlock a unit.')+`<div class="searchrow"><input id="phrase-search" type="search" placeholder="Search English, Japanese, or romaji…" aria-label="Search phrases" value="${esc(phraseQuery)}"><select id="phrase-unit" aria-label="Filter by unit"><option value="">All situations</option>${COURSE.map((u,i)=>`<option value="${i}" ${phraseFilter===String(i)?'selected':''}>${u.title}</option>`).join('')}</select><button class="secondary ${savedOnly?'filter-save active':''}" id="saved-only">${icon('bookmark')}${savedOnly?'Saved only':'Favourites'}</button></div><div class="phrase-search-count">${filtered.length} phrases${savedOnly?' · your favourites':''}</div><div class="phrase-list">${filtered.length?filtered.map(c=>`<article class="phrase"><button class="audio-icon" data-speak="${c.id}" aria-label="Listen to ${esc(c.p[2])}">${icon('sound')}</button><div class="phrase-text"><div class="jp" lang="ja">${c.p[0]}</div>${state.settings.romaji?`<div class="romaji">${c.p[1]}</div>`:''}<div class="meaning">${c.p[2]}</div></div><button class="filter-save ${state.saved.includes(c.id)?'active':''}" data-save="${c.id}" aria-label="${state.saved.includes(c.id)?'Unsave':'Save'} ${esc(c.p[2])}" aria-pressed="${state.saved.includes(c.id)}">${icon('bookmark')}</button></article>`).join(''):'<div class="empty">No phrases found. Try another search or situation.</div>'}</div>`;}
function conversationPage(){return intro('PUT IT INTO WORDS','A small rehearsal. A real-world moment.','Practise both sides of a travel exchange. Listen to your partner, say your reply aloud, then choose or type it.')+`<div class="tabs" aria-label="Conversation difficulty"><button data-convmode="guided" class="${convMode==='guided'?'active':''}">Guided replies</button><button data-convmode="recall" class="${convMode==='recall'?'active':''}">From memory</button></div><div class="grid2">${SCENARIOS.map((s,i)=>`<div class="featurecard"><span class="unit-icon" style="background:${['#F1E2D7','#E4EDF0','#E9EBD7','#E0EBDF'][i]}">${icon(s.icon)}</span><div class="eyebrow" style="margin:0">${s.place}</div><h2>${s.title}</h2><p>${s.desc}</p><small class="muted">5 turns · ${state.conversations[i]?'Practised ✓':'Ready when you are'}</small><button class="secondary" data-conversation="${i}">Step into the conversation${icon('arrow')}</button></div>`).join('')}</div><div class="info">These are guided practice scenes with set replies, rather than a live chat tutor. “From memory” hides choices and accepts Japanese or the model romaji. Speaking is self-assessed; no automatic pronunciation score.</div>`;}
function kanaPage(){return intro('A SOUND FOUNDATION','Meet the sounds of Japanese.','Hiragana writes native Japanese sounds; katakana often writes borrowed words. Learn a row at a time, then test what you remember.')+`<div class="tabs"><button data-kana="1" class="${kanaType===1?'active':''}">Hiragana · あ</button><button data-kana="2" class="${kanaType===2?'active':''}">Katakana · ア</button></div><div class="section-title"><p class="muted" style="font-size:12px">Tap a character to hear its sound.</p><button class="secondary" id="kana-quiz">Practise 10 sounds${icon('arrow')}</button></div><div class="kana-table">${KANA_ROWS.map(row=>Array.from({length:5},(_,i)=>{let c=row[kanaType][i];return c&&c!==' '?`<button class="kana-cell" data-kanaspeak="${c}" aria-label="${c}, ${row[3][i]}"><span lang="ja">${c}</span><small>${row[3][i]}</small></button>`:'<span></span>';}).join('')).join('')}</div><div class="outline"><h3>Small characters, big differences</h3><p>きゃ / キャ = kya, きゅ / キュ = kyu, きょ / キョ = kyo. Small ゃ, ゅ, ょ combine with an i-row sound (き, し, ち, に, ひ, み, り and voiced variants). Small っ / ッ creates a short pause: きって (kitte, stamp). A long vowel lasts two beats: おばさん (obasan, aunt) and おばあさん (obāsan, grandmother) are different words. Katakana often marks a long vowel with ー.</p><p>し = shi, ち = chi, つ = tsu, ふ = fu. を is usually pronounced “o” as a particle; は is “wa” when it marks the topic. Japanese r is a quick tongue tap, between English r and l.</p></div>`;}
function progressPage(){return intro('YOUR TRAVEL JOURNAL','Look how far you’ve come.','A conversation starts with a few words. Every lesson gives you a few more.')+`<div class="statgrid"><div class="statbox"><strong>${state.completed.length}<span style="display:inline;font-size:16px"> / 30</span></strong><span>LESSONS COMPLETE</span></div><div class="statbox"><strong>${Object.keys(state.reviews).length}</strong><span>PHRASES LEARNED</span></div><div class="statbox"><strong>${streak()}</strong><span>DAY STREAK</span></div></div><div class="card"><div class="section-title"><h3>Your practical milestones</h3><span>${Math.round(state.completed.length/30*100)}% of the path</span></div>${COURSE.map((u,ui)=>{let count=u.lessons.filter((l,li)=>state.completed.includes(`${ui}-${li}`)).length;return `<div class="lesson-row"><span class="lesson-node ${count===3?'done':''}" style="background:${count===3?'#E7EEDB':'#F1F3EC'}">${icon(count===3?'check':u.icon)}</span><div class="lessontext"><strong>${u.goal}</strong><small>${u.title} · ${count}/3 lessons</small></div><span class="muted" style="font-size:11px">${count===3?'Practised':'In progress'}</span></div>`;}).join('')}</div><div class="info">Completion means you passed the app’s recall checks, not a certified language level. For comfortable travel conversations, keep practising listening and responding with real speakers. This course builds practical beginner foundations.</div><div class="resource">Keep going with native-speaker audio and fuller lessons in the Japan Foundation’s free <a href="https://www.irodori.jpf.go.jp/en/starter/pdf.html" target="_blank" rel="noopener">Irodori Starter course ↗</a>. Tabi’s original practice content is independent and is not an official Japan Foundation course.</div>`;}
function settingsPage(){return intro('MAKE YOURSELF AT HOME','Your learning, your pace.','A comfortable routine is the one you come back to.')+offlineSettings()+`<div class="card"><div class="settings-row"><div><h3>Romaji support</h3><p>Show Latin-script readings on learning cards, Japanese answer choices, and in your phrasebook.</p></div><button class="toggle ${state.settings.romaji?'on':''}" id="romaji-toggle" role="switch" aria-checked="${state.settings.romaji}" aria-label="Romaji support"><i></i></button></div><div class="settings-row"><div><h3>Your daily goal</h3><p>A new lesson earns 30 XP; a revisit earns 10 XP.</p></div><select id="daily-goal" aria-label="Daily XP goal">${[15,30,50].map(n=>`<option ${state.settings.goal===n?'selected':''} value="${n}">${n} XP / day</option>`).join('')}</select></div><div class="settings-row"><div><h3>Japanese audio</h3><p>${voiceStatusText()}</p></div><button class="secondary" id="audio-test">${icon('sound')}Test</button></div><div class="settings-row"><div><h3>Your progress backup</h3><p>Progress stays in this browser. Export a backup to keep it or move to another device.</p></div><button class="secondary" id="export">${icon('download')}Export</button></div><div class="settings-row"><div><h3>Import a backup</h3><p>A valid Tabi backup replaces the progress on this browser.</p></div><button class="secondary" id="import-btn">Import</button><input type="file" id="import-file" accept="application/json,.json" hidden></div><div class="settings-row" style="border:0"><div><h3>Progress storage</h3><p>${storageOK?'Browser storage is available. Back up before clearing browsing data.':'Storage is unavailable. Export a backup before leaving this page.'}</p></div></div></div><div class="outline"><h3>Built for useful conversations</h3><p>30 progressive lessons · 120 practical phrases · 10 travel units. Learn through explanations, recognition, listening, sentence building, recall, and speaking aloud. Pass with at least 80% first-attempt accuracy and correct every missed answer to unlock the next lesson.</p><p>Audio uses your device’s Japanese speech synthesis. Optional microphone recording stays on this device and is discarded when the exercise closes. Speaking is self-assessed and is not a pronunciation evaluation.</p></div><p class="resource mt">For additional authentic listening practice: <a href="https://www.irodori.jpf.go.jp/en/starter/pdf.html" target="_blank" rel="noopener">Japan Foundation · Irodori Starter ↗</a>. This independent app is a starting point for travel Japanese, not a guarantee of conversational proficiency.</p>`;}
function bind(){window.TabiStudio?.bind();document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{if(page==='studio')window.TabiStudio.leave();page=b.dataset.nav;render();window.scrollTo(0,0);});document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{let n=+b.dataset.unit;expanded.has(n)?expanded.delete(n):expanded.add(n);/* keep current unit collapsible */const next=nextLesson();const html=unitCard(COURSE[n],n,next);b.closest('.unit').outerHTML=html;bind();});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>startLesson(...b.dataset.lesson.split('-').map(Number)));if($('#continue'))$('#continue').onclick=()=>{const n=nextLesson();n?startLesson(...n):startReview(false);};if($('#day-audio'))$('#day-audio').onclick=()=>speak(dayPhrase()[0]);if($('#review-due'))$('#review-due').onclick=()=>startReview(true);if($('#review-all'))$('#review-all').onclick=()=>startReview(false);if($('#phrase-search'))$('#phrase-search').oninput=e=>{const v=e.target.value,pos=e.target.selectionStart;phraseQuery=v;render();$('#phrase-search').focus();$('#phrase-search').setSelectionRange(pos,pos);};if($('#phrase-unit'))$('#phrase-unit').onchange=e=>{phraseFilter=e.target.value;render();};if($('#saved-only'))$('#saved-only').onclick=()=>{savedOnly=!savedOnly;render();};document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{let id=b.dataset.save;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];save();render();});document.querySelectorAll('[data-speak]').forEach(b=>b.onclick=()=>speak(byId(b.dataset.speak).p[0]));document.querySelectorAll('[data-kana]').forEach(b=>b.onclick=()=>{kanaType=+b.dataset.kana;render();});document.querySelectorAll('[data-kanaspeak]').forEach(b=>b.onclick=()=>speak(b.dataset.kanaspeak));if($('#kana-quiz'))$('#kana-quiz').onclick=startKana;document.querySelectorAll('[data-convmode]').forEach(b=>b.onclick=()=>{convMode=b.dataset.convmode;render();});document.querySelectorAll('[data-conversation]').forEach(b=>b.onclick=()=>startConversation(+b.dataset.conversation));if($('#romaji-toggle'))$('#romaji-toggle').onclick=()=>{state.settings.romaji=!state.settings.romaji;save();render();};if($('#daily-goal'))$('#daily-goal').onchange=e=>{state.settings.goal=+e.target.value;save();render();};if($('#audio-test'))$('#audio-test').onclick=()=>speak('こんにちは。日本へようこそ。');if($('#export'))$('#export').onclick=exportBackup;if($('#import-btn'))$('#import-btn').onclick=()=>$('#import-file').click();if($('#import-file'))$('#import-file').onchange=importBackup;}
function exportBackup(){const b=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`tabi-progress-${dateKey()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Your progress backup is ready.');}
async function importBackup(e){try{const f=e.target.files[0];if(!f)return;if(f.size>2000000)throw Error();const incoming=validate(JSON.parse(await f.text()));if(!confirm('Replace this browser’s progress with the selected backup? Export your current progress first if you want to keep it.'))return;state=incoming;save();render();toast('Your progress is restored. Welcome back.');}catch(err){toast('This is not a valid Tabi progress backup.');}}
function addXP(n,id){const d=dateKey();state.history[d]||={xp:0,lessons:[]};if(id&&state.history[d].lessons.includes(id))return 0;state.history[d].xp+=n;if(id)state.history[d].lessons.push(id);return n;}
function schedule(id,good){if(!byId(id))return;let prev=state.reviews[id],level=good?Math.min(5,(prev?.level??-1)+1):0;state.reviews[id]={level,due:Date.now()+(good?[1,3,7,14,30,30][level]:.02)*86400000};}
function distractors(card,kind){let correct=['meaning','listen'].includes(kind)?card.p[2]:card.p[0],others=shuffle(cards.filter(c=>c.p[0]!==card.p[0]&&c.p[2]!==card.p[2])).slice(0,3).map(c=>['meaning','listen'].includes(kind)?c.p[2]:c.p[0]);return shuffle([correct,...others]);}
function question(type,c){return {type,c,options:['meaning','listen'].includes(type)?distractors(c,type):null};}
function startLesson(u,l){if(!unlocked(u,l)){toast('Complete the previous lesson first.');return;}let lesson=COURSE[u].lessons[l],cs=cards.filter(c=>c.ui===u&&c.li===l);let steps=[{type:'intro',lesson},...cs.map(c=>question('teach',c)),...shuffle(cs).map(c=>question('meaning',c)),...shuffle(cs).slice(0,2).map(c=>question('listen',c)),...shuffle(cs).slice(0,2).map(c=>question('tiles',c)),...shuffle(cs).slice(0,2).map(c=>question('recall',c))];if(l===2){const prior=shuffle(cards.filter(c=>c.ui===u&&c.li<l)).slice(0,3);steps.push(...prior.map(c=>question('recall',c)));}steps.push(question('speak',cs[3]));openSession({kind:'lesson',title:lesson[0],u,l,cards:cs,steps});}
function startReview(due){let cs=shuffle(due?dueCards():cards.filter(c=>state.reviews[c.id])).slice(0,10);if(!cs.length)return toast('Learn a lesson first to build your review collection.');openSession({kind:'review',title:due?'A little spaced review':'From memory',cards:cs,steps:cs.map(c=>question(due?(Math.random()>.45?'recall':'listen'):'recall',c))});}
function startKana(){let list=[];KANA_ROWS.forEach(r=>[...r[kanaType]].forEach((c,i)=>{if(c!==' ')list.push({p:[c,r[3][i],r[3][i],''],id:null});}));let cs=shuffle(list).slice(0,10);openSession({kind:'kana',title:'Know your kana',cards:cs,steps:cs.map(c=>({type:'kana',c,options:shuffle([c.p[2],...shuffle([...new Set(list.map(x=>x.p[2]))].filter(x=>x!==c.p[2])).slice(0,3)])}))});}
function startConversation(i){let sc=SCENARIOS[i];openSession({kind:'conversation',title:sc.title,scenario:i,cards:[],steps:sc.turns.map(t=>({type:'conversation',turn:t,c:cards.find(c=>c.p[0]===t[2]),options:shuffle(t[3])}))});}
function openSession(data){session={...data,index:0,wrong:[],missed:new Set(),answers:0,correct:0,selected:null,typed:'',tiles:[],checked:false,feedback:null,remedial:false,oral:false};document.body.style.overflow='hidden';showStep();}
let recorder=null,recordStream=null,recordURL=null,recording=false;
function clearRecording(){if(recorder&&recorder.state!=='inactive')recorder.stop();recordStream?.getTracks().forEach(t=>t.stop());recorder=null;recordStream=null;recording=false;if(recordURL){URL.revokeObjectURL(recordURL);recordURL=null;}}
function closeSession(){if(!session)return;if(session.result||confirm('Leave this practice? Finished lessons stay saved, but this session will restart.')){clearRecording();window.speechSynthesis?.cancel();session=null;$('#overlay').innerHTML='';document.body.style.overflow='';render();}}
function current(){return session.steps[session.index];}
function showStep(){let s=session;if(!s)return;let q=current();if(!q)return finishSession();s.selected=null;s.typed='';s.tiles=[];s.checked=false;s.feedback=null;s.oral=false;s.wordPool=q.type==='tiles'?shuffle(q.c.p[1].split(' ').map((w,i)=>({w,id:i}))):[];renderSession();$('#overlay .exercise')?.focus();}
function renderSession(){let s=session,q=current();if(!q)return;let progress=s.index/s.steps.length*100;$('#overlay').innerHTML=`<section class="screen" role="dialog" aria-modal="true" aria-label="${esc(s.title)}"><div class="screen-top"><button class="close" id="close-session" aria-label="Leave lesson">×</button><div class="progressbar" aria-label="Session progress"><i style="width:${progress}%"></i></div><small>${s.remedial?'RETRY':`${s.index+1} / ${s.steps.length}`}</small></div><div class="exercise" tabindex="-1">${exerciseHTML(q)}</div><footer class="lesson-footer"><div class="footer-inner">${footerHTML(q)}<button class="primary" id="next-step" ${canContinue(q)?'':'disabled'}>${s.checked?'Continue':['intro','teach'].includes(q.type)?'Continue':q.type==='speak'?'Finish lesson':'Check answer'}${icon('arrow')}</button></div></footer></section>`;bindSession();}
function exerciseHTML(q){const s=session,p=q.c?.p;switch(q.type){case'intro':return `<div class="eyebrow">UNIT ${s.u+1} · LESSON ${s.l+1}</div><h2>${q.lesson[0]}</h2><p class="sub">Today, you can: ${q.lesson[1].charAt(0).toLowerCase()+q.lesson[1].slice(1)}</p><div class="outline" style="margin:25px 0"><h3>A pattern to take with you</h3><p style="font-size:15px;line-height:1.9">${q.lesson[2]}</p></div><div class="info">First, meet four phrases. Then listen, build, and recall them without hints. Say each one aloud. Pass with 80% first-attempt accuracy and correct any mistakes to keep progressing.</div>`;
case'teach':return `<div class="eyebrow">MEET A NEW PHRASE</div><h2>Listen. Notice. Say it aloud.</h2><p class="sub">Picture yourself using this in Japan.</p><div class="teach-card"><div class="jp" lang="ja">${p[0]}</div>${state.settings.romaji?`<div class="romaji">${p[1]}</div>`:''}<div class="meaning">${p[2]}</div><button class="audio-icon" id="question-audio" aria-label="Listen">${icon('sound')}</button><small>${p[3]}</small></div><button class="linkbtn" id="slow-audio">${icon('sound')}Listen slowly</button>`;
case'meaning':return `<div class="eyebrow">CONNECT THE MEANING</div><h2>What does this mean?</h2><div class="teach-card"><div class="jp" lang="ja">${p[0]}</div>${state.settings.romaji?`<div class="romaji">${p[1]}</div>`:''}<button class="audio-icon" id="question-audio" aria-label="Listen">${icon('sound')}</button></div>${optionsHTML(q)}`;
case'listen':return `<div class="eyebrow">${hasVoice()?'TRAIN YOUR EAR':'READING PRACTICE · AUDIO UNAVAILABLE'}</div><h2>${hasVoice()?'What does the phrase you hear mean?':'What does this phrase mean?'}</h2>${hasVoice()?`<button class="listen-big" id="question-audio" aria-label="Play Japanese audio">${icon('sound')}</button><button class="slow" id="slow-audio">Listen slowly</button>`:`<div class="info"><span lang="ja">${p[0]}</span><br><small>Enable a Japanese device voice in Settings for listening exercises.</small></div>`}${optionsHTML(q)}`;
case'tiles':return `<div class="eyebrow">BUILD THE PHRASE</div><h2>How would you say this?</h2><p class="sub" style="font-size:19px;color:var(--ink);margin-top:25px">“${p[2]}”</p><p class="sub mt">Put the romaji words in order. Tap an answer word to move it back.</p><div class="tile-answer" aria-label="Your sentence">${s.tiles.map(id=>{const w=s.wordPool.find(x=>x.id===id);return `<button class="tile" data-tile-remove="${id}" ${s.checked?'disabled':''}>${w.w}</button>`;}).join('')}</div><div class="tile-pool">${s.wordPool.map(w=>`<button class="tile ${s.tiles.includes(w.id)?'hidden':''}" data-tile="${w.id}" ${s.checked?'disabled':''}>${w.w}</button>`).join('')}</div>${s.checked?`<div class="info"><span lang="ja">${p[0]}</span><br>${p[1]}</div>`:''}`;
case'recall':return `<div class="eyebrow">FROM MEMORY</div><h2>Bring it back without hints.</h2><p class="sub mt" style="font-size:21px;color:var(--ink)">“${p[2]}”</p><p class="sub mt">Type the Japanese or romaji. Long vowels can be typed with or without a macron (ō).</p><input class="answer-input" id="typed-answer" lang="ja" aria-label="Your Japanese or romaji answer" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Your answer…" value="${esc(s.typed)}" ${s.checked?'disabled':''}>${s.checked?`<div class="info"><span lang="ja">${p[0]}</span><br>${p[1]}<br><small>${p[3]}</small></div>`:''}`;
case'speak':return `<div class="eyebrow">TAKE IT OFF THE SCREEN</div><h2>One last step. Say it for real.</h2><p class="sub">Imagine a person is in front of you. Say the phrase below, then try saying it again with your eyes closed.</p><div class="teach-card"><div class="meaning" style="font-size:22px">${p[2]}</div><button class="secondary" id="reveal-speech">Show model & listen${icon('sound')}</button><div id="speech-model" class="romaji" hidden><span lang="ja">${p[0]}</span><br>${p[1]}</div></div><div class="speaking"><h4>Hear yourself back <small class="muted">· optional</small></h4><p>Record yourself and compare with the model. This is private, on-device practice, without automatic pronunciation scoring.</p><button class="secondary" id="record">${icon('mic')}Record my voice</button><div id="record-output"></div></div><div class="checklist"><label><input id="oral-check" type="checkbox" ${s.oral?'checked':''}>I have said this aloud without looking.</label></div>`;
case'kana':return `<div class="eyebrow">KNOW YOUR KANA</div><h2>What sound is this?</h2><div class="teach-card"><div class="jp" lang="ja" style="font-size:75px">${p[0]}</div><button class="audio-icon" id="question-audio" aria-label="Listen to the kana">${icon('sound')}</button></div>${optionsHTML(q)}`;
case'conversation':{let t=q.turn;return `<div class="eyebrow">${SCENARIOS[s.scenario].place} · TURN ${Math.min(s.index+1,5)}</div><h2>${s.title}</h2><div class="chatbubble" id="partner"><div class="eyebrow" style="margin-bottom:10px">YOUR CONVERSATION PARTNER</div><div class="jp" lang="ja">${t[0]}</div><button class="linkbtn" id="partner-audio">${icon('sound')}Listen</button><button class="linkbtn" id="translation" style="margin-left:15px">Show translation</button><div class="meaning">${t[1]}</div></div><p class="sub mt" style="color:var(--ink);font-size:16px">${t[4]}</p><p class="sub" style="margin-top:9px">Say your reply aloud, then ${convMode==='guided'?'choose it':'type it in Japanese or romaji'}.</p>${convMode==='guided'?optionsHTML(q):`<input class="answer-input" id="typed-answer" aria-label="Your reply in Japanese or romaji" autocomplete="off" autocapitalize="off" spellcheck="false" placeholder="Your reply…" value="${esc(s.typed)}" ${s.checked?'disabled':''}>`}${s.checked?`<div class="info"><span lang="ja">${t[2]}</span>${q.c?`<br>${q.c.p[1]}`:''}</div>`:''}`;}}}
function optionLabel(answer){
  const phrase=cards.find(card=>card.p[0]===answer);
  const reading=state.settings.romaji&&phrase?phrase.p[1]:null;
  return `<span class="option-copy"><span${phrase?' class="option-jp" lang="ja"':''}>${esc(answer)}</span>${reading?`<span class="option-romaji" lang="en">${esc(reading)}</span>`:''}</span>`;
}
function optionsHTML(q){let s=session,correct=['meaning','listen','kana'].includes(q.type)?q.c.p[2]:q.type==='conversation'?q.turn[2]:q.c.p[0];return `<div class="options" role="group" aria-label="Answer choices">${q.options.map((o,i)=>`<button class="option ${s.selected===i?'selected':''} ${s.checked&&o===correct?'correct':''} ${s.checked&&s.selected===i&&o!==correct?'wrong':''}" data-option="${i}" ${s.checked?'disabled':''}><b>${i+1}</b>${optionLabel(o)}</button>`).join('')}</div>`;}

function canContinue(q){if(session.checked)return true;if(['intro','teach'].includes(q.type))return true;if(q.type==='speak')return session.oral;if(q.type==='tiles')return session.tiles.length===session.wordPool.length;if(q.type==='recall'||(q.type==='conversation'&&convMode==='recall'))return session.typed.trim().length>0;return session.selected!==null;}
function footerHTML(q){let s=session;if(s.checked){let f=s.feedback;return `<div class="feedback ${f.good?'good':'bad'}" role="status"><strong>${f.good?'Nicely done.':'A little more practice.'}</strong>${f.good?'One step closer to your next conversation.':`Model: ${esc(f.model)}${s.remedial?'':' · We’ll try this again at the end.'}`}</div>`;}return `<div class="footer-label">${q.type==='intro'?'Learn the pattern, then make it yours.':q.type==='teach'?'Listen and repeat at your own pace.':q.type==='speak'?'Speaking is self-assessed.':'Take your time. You’re here to learn.'}<div class="footerhint">Enter to continue</div></div>`;}
function bindSession(){const s=session,q=current();$('#close-session').onclick=closeSession;$('#next-step').onclick=advance;document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{s.selected=+b.dataset.option;renderSession();});if($('#typed-answer'))$('#typed-answer').oninput=e=>{s.typed=e.target.value;$('#next-step').disabled=!canContinue(q);};if($('#question-audio'))$('#question-audio').onclick=()=>speak(q.c.p[0]);if($('#slow-audio'))$('#slow-audio').onclick=()=>speak(q.c.p[0],.6);document.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{s.tiles.push(+b.dataset.tile);renderSession();});document.querySelectorAll('[data-tile-remove]').forEach(b=>b.onclick=()=>{s.tiles=s.tiles.filter(x=>x!==+b.dataset.tileRemove);renderSession();});if($('#oral-check'))$('#oral-check').onchange=e=>{s.oral=e.target.checked;$('#next-step').disabled=!s.oral;};if($('#reveal-speech'))$('#reveal-speech').onclick=()=>{$('#speech-model').hidden=false;speak(q.c.p[0]);};if($('#record'))$('#record').onclick=recordVoice;if($('#partner-audio'))$('#partner-audio').onclick=()=>speak(q.turn[0]);if($('#translation'))$('#translation').onclick=()=>{$('#partner').classList.toggle('revealed');$('#translation').textContent=$('#partner').classList.contains('revealed')?'Hide translation':'Show translation';};}
async function recordVoice(){if(recording){recorder?.stop();$('#record').textContent='Record again';return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Recording is unavailable in this browser. Say the phrase aloud and compare with the model.');return;}clearRecording();const activeSession=session;try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});if(session!==activeSession||current()?.type!=='speak'){clearRecording();return;}let chunks=[];recorder=new MediaRecorder(recordStream);recorder.ondataavailable=e=>chunks.push(e.data);recorder.onstop=()=>{recordStream?.getTracks().forEach(t=>t.stop());recording=false;if(session!==activeSession||!$('#record-output'))return;recordURL=URL.createObjectURL(new Blob(chunks,{type:recorder.mimeType||'audio/webm'}));$('#record-output').innerHTML=`<audio controls src="${recordURL}" style="width:100%;margin-top:15px" aria-label="Your voice recording"></audio>`;$('#record').textContent='Record again';};recorder.start();recording=true;$('#record').textContent='Stop recording';setTimeout(()=>{if(recording&&recorder?.state==='recording')recorder.stop();},20000);}catch(e){clearRecording();toast('Microphone access is unavailable. You can still practise aloud and continue.');}}
function advance(){const s=session;if(!s)return;if(s.result)return;const q=current();if(!canContinue(q))return;if(s.checked||['intro','teach','speak'].includes(q.type)){if(q.type==='speak')clearRecording();s.index++;return showStep();}let good=false,model=q.c?.p[1]||'';if(q.type==='tiles'){const v=s.tiles.map(id=>s.wordPool.find(x=>x.id===id).w).join(' ');good=normalize(v)===normalize(q.c.p[1]);}else if(q.type==='recall'){good=accepted(s.typed,q.c.p);}else if(q.type==='conversation'){good=convMode==='guided'?q.options[s.selected]===q.turn[2]:q.c?accepted(s.typed,q.c.p):normalize(s.typed)===normalize(q.turn[2]);model=q.c?.p[1]||q.turn[2];}else{const answer=q.options[s.selected],target=['meaning','listen','kana'].includes(q.type)?q.c.p[2]:q.c.p[0];good=answer===target;model=q.type==='kana'?q.c.p[2]:q.c.p[1];}if(!s.remedial){s.answers++;if(good)s.correct++;}if(!good){if(q.c?.id)s.missed.add(q.c.id);if(!s.wrong.includes(q))s.wrong.push(q);}s.checked=true;s.feedback={good,model};renderSession();}
function finishSession(){let s=session;if(s.wrong.length){s.steps=[...s.wrong];s.wrong=[];s.index=0;s.remedial=true;toast('Let’s give those tricky phrases another go.');return showStep();}s.result=true;let accuracy=s.answers?Math.round(s.correct/s.answers*100):100,passed=accuracy>=80,xp=0;if(s.kind==='lesson'){if(passed){const id=`${s.u}-${s.l}`,isNew=!state.completed.includes(id);if(isNew)state.completed.push(id);xp=addXP(isNew?30:10,id);s.cards.forEach(c=>schedule(c.id,!s.missed.has(c.id)));}}else if(s.kind==='review'){s.cards.forEach(c=>schedule(c.id,!s.missed.has(c.id)));xp=addXP(10);}else if(s.kind==='conversation'){state.conversations[s.scenario]={date:dateKey(),accuracy};xp=addXP(15,`conversation-${s.scenario}-${convMode}`);}else xp=addXP(10,'kana-'+kanaType);save();const failed=s.kind==='lesson'&&!passed;$('#overlay').innerHTML=`<section class="screen" role="dialog" aria-modal="true" aria-label="Practice complete"><div class="screen-top"><button class="close" id="close-session" aria-label="Close result">×</button><div class="progressbar"><i style="width:100%"></i></div></div><div class="exercise result"><div class="result-medal">${icon(failed?'leaf':'flag')}</div><div class="eyebrow">${failed?'GETTING THERE, ONE STEP AT A TIME':'A LITTLE MORE JAPANESE, A LITTLE MORE CONFIDENCE'}</div><h2>${failed?'You’ve met the words. Let’s make them stick.':s.kind==='lesson'?'Another step on your journey.':'Practice, beautifully done.'}</h2><p>${failed?`Your first-attempt accuracy was ${accuracy}%. Reach 80% to unlock the next lesson. You corrected every missed answer — now try the lesson again.`:s.kind==='lesson'?'You learned, listened, recalled, and spoke aloud. Your phrases are now in your review collection.':s.kind==='conversation'?'You completed every turn. Try the scene from memory next, and keep saying your replies aloud.':'You brought your Japanese back from memory. That’s how it stays with you.'}</p><div class="resultstats"><div><b>${xp}</b><small>XP EARNED</small></div><div><b>${accuracy}%</b><small>FIRST-TRY ACCURACY</small></div><div><b>${streak()}</b><small>DAY STREAK</small></div></div>${!storageOK?'<div class="info">Progress could not be saved in this browser. Export a backup from Settings before leaving.</div>':''}</div><footer class="lesson-footer"><div class="footer-inner"><button class="secondary" id="back-path">Back to ${s.kind==='lesson'?'path':'practice'}</button><button class="primary" id="result-next">${failed?'Try lesson again':s.kind==='lesson'&&nextLesson()?'Next lesson':'Keep exploring'}${icon('arrow')}</button></div></footer></section>`;$('#close-session').onclick=closeSession;$('#back-path').onclick=()=>closeSession();$('#result-next').onclick=()=>{if(failed){const u=s.u,l=s.l;startLesson(u,l);}else if(s.kind==='lesson'&&nextLesson()){startLesson(...nextLesson());}else closeSession();};}
document.addEventListener('keydown',e=>{if(!session)return;if(e.key==='Escape'){closeSession();return;}if(e.key==='Enter'&&!e.isComposing&&e.target.tagName!=='BUTTON'){e.preventDefault();if(session.result)$('#result-next')?.click();else if(!$('#next-step')?.disabled)advance();}if(!session.result&&!session.checked&&current()?.options&&/^[1-4]$/.test(e.key)&&e.target.tagName!=='INPUT'){session.selected=+e.key-1;renderSession();}});
function pwaState(){return window.TabiPWA?.snapshot()||{phase:'unsupported',online:navigator.onLine!==false,installed:false,update:false};}
function offlineDescription(s=pwaState()){
  if(s.phase==='ready')return s.online?'Ready offline · all 30 lessons saved on this device.':'You’re offline · lessons, kana, conversations and progress are available.';
  if(s.phase==='preparing')return 'Saving Tabi for offline use… Keep this app open while connected.';
  if(s.phase==='unsupported')return 'Open Tabi in Safari or Chrome to install it and save lessons offline.';
  return s.online?'Offline download incomplete. Retry while connected.':'Offline files are incomplete. Reconnect to finish the download.';
}
function updatePwaUI(){const s=pwaState(),bar=$('#pwa-status');if(bar){bar.className='offline-strip '+(s.phase==='ready'?'ready':s.phase==='error'?'needs-download':'');bar.innerHTML=`<span><span class="connection-dot"></span>${s.phase==='ready'?(s.online?'Ready offline':'Offline · ready to learn'):s.phase==='preparing'?'Saving for offline…':s.phase==='error'?'Offline setup incomplete':'Install for offline learning'}</span><div class="offline-actions">${s.phase==='error'?'<button data-pwa-action="retry">Retry download</button>':''}${s.update?'<button data-pwa-action="update">Update app</button>':''}<button data-pwa-action="install">${s.installed?'Offline settings':'Install app'} ${icon('download')}</button></div>`;}
  const description=$('#offline-description');if(description)description.textContent=offlineDescription(s);
  const installState=$('#pwa-install-state');if(installState)installState.textContent=s.installed?'Home Screen app':'Install on this phone';
  const verify=$('#verify-offline');if(verify)verify.disabled=s.phase!=='ready';
  const retry=$('#retry-offline');if(retry)retry.hidden=s.phase!=='error';
  const update=$('#update-pwa');if(update)update.hidden=!s.update;
  const voice=$('#offline-audio-hint');if(voice)voice.textContent=voiceStatusText();
}
function offlineSettings(){const s=pwaState();return `<section class="card offline-settings"><div class="eyebrow">TAKE TABI WITH YOU</div><div class="section-title"><h2>Learn anywhere. Even offline.</h2><span class="pill" id="pwa-install-state">${s.installed?'Home Screen app':'Install on this phone'}</span></div><p id="offline-description" class="offline-description">${offlineDescription(s)}</p><div class="pwa-buttons"><button class="primary" data-pwa-action="install">${icon('download')}Install & setup guide</button><button class="secondary" data-pwa-action="verify" id="verify-offline" ${s.phase==='ready'?'':'disabled'}>Check offline files</button><button class="secondary" data-pwa-action="retry" id="retry-offline" ${s.phase==='error'?'':'hidden'}>Retry download</button><button class="secondary" data-pwa-action="update" id="update-pwa" ${s.update?'':'hidden'}>Update app</button></div><div class="outline"><h3>Before your trip</h3><ol class="install-steps"><li>Install Tabi on your Home Screen while connected.</li><li>Open the installed app once online. Wait for <strong>Ready offline</strong>.</li><li>Try it in airplane mode: reopen the app and start a lesson.</li></ol><p>All course content is saved automatically. Progress and favourites stay on this device. Export a backup before moving from the browser to the installed app, as their storage can be separate.</p><p id="offline-audio-hint">${voiceStatusText()}</p><p>External learning links need an internet connection.</p></div><button class="linkbtn" data-pwa-action="storage">Help keep offline storage available ${icon('arrow')}</button></section>`;}
let installReturnFocus=null;
function showInstallHelp(){const s=pwaState();installReturnFocus=document.activeElement;$('#pwa-dialog').innerHTML=`<div class="install-backdrop"><section class="install-dialog" role="dialog" aria-modal="true" aria-labelledby="install-heading"><button class="close" data-pwa-action="dismiss" aria-label="Close install guide">×</button><span class="brandmark" aria-hidden="true">旅</span><div class="eyebrow">JAPANESE, WHEREVER YOU GO</div><h2 id="install-heading">Make room for a little adventure.</h2><p class="muted">Install Tabi for quick access and offline learning.</p><h3>On iPhone or iPad</h3><ol class="install-steps"><li>Open this URL in <strong>Safari</strong>.</li><li>Tap <strong>Share</strong>, then <strong>Add to Home Screen</strong>.</li><li>If shown, keep <strong>Open as Web App</strong> on, then tap <strong>Add</strong>.</li><li>Open Tabi from the new icon while connected and wait for <strong>Ready offline</strong>.</li></ol><h3>On Android</h3><p>Open Tabi in Chrome. Choose <strong>Install app</strong> or <strong>Add to Home screen</strong> from the browser menu.</p>${s.canPrompt?'<button class="primary" data-pwa-action="native-install">Install Tabi now</button>':''}<div class="info">${offlineDescription(s)}<br>Progress is stored on this device. Export a backup in Settings before switching to the installed app.</div><button class="secondary" data-pwa-action="dismiss">Got it</button></section></div>`;$('#pwa-dialog .close').focus();}
function closeInstallHelp(){$('#pwa-dialog').innerHTML='';installReturnFocus?.focus();}
window.addEventListener('tabi:pwa-state',updatePwaUI);
window.addEventListener('tabi:pwa-notice',event=>toast(event.detail));
window.speechSynthesis?.addEventListener('voiceschanged',updatePwaUI);
document.addEventListener('click',async event=>{const action=event.target.closest('[data-pwa-action]')?.dataset.pwaAction;if(!action)return;
  if(action==='install'){showInstallHelp();return;}
  if(action==='dismiss'){closeInstallHelp();return;}
  if(action==='native-install'){await window.TabiPWA?.install();return;}
  if(action==='verify'){await window.TabiPWA?.check();return;}
  if(action==='retry'){await window.TabiPWA?.retry();return;}
  if(action==='storage'){await window.TabiPWA?.requestStorage();return;}
  if(action==='update'){if(session&&!session.result){toast('Finish or leave your lesson before updating. Your completed progress is saved.');return;}window.TabiPWA?.update();}
});
document.addEventListener('keydown',event=>{const dialog=$('#pwa-dialog [role="dialog"]');if(!dialog)return;if(event.key==='Escape'){closeInstallHelp();return;}if(event.key==='Tab'){const nodes=dialog.querySelectorAll('button:not([hidden])');const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
render();
